using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
namespace UnturnedModManager {
 public sealed class InstalledContentChangedException : Exception {public InstalledContentChangedException(string target):base(L.Get("Text163")+target){}}
 public sealed class AssistantOwned {public string relative,hash,originalHash;public bool hadOriginal;}
 public sealed class AssistantRecord {public string gameRoot,version,product;public List<AssistantOwned> files;}
 public sealed class ReconciliationPlan {
  public Package Package;public string AssistantState,ManagerRecordHash,AssistantRecordHash,PackageSignature;public int Files,Originals,Retained,RetainedDifferences,BackupDifferences;public bool AlreadyCurrent;
 }
 public partial class Engine {
  public static string DefaultAssistantState(string root){return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"UnturnedAITraditional","Installs",Data.Key(root.TrimEnd('\\')).Substring(0,20));}
  string Original(OwnedFile file){if(string.IsNullOrEmpty(file.backupReference))return Original(file.target);if(!System.Text.RegularExpressions.Regex.IsMatch(file.backupReference,@"^ImportedOriginals/[a-f0-9]{32}/[a-f0-9]{24}\.bak$",System.Text.RegularExpressions.RegexOptions.IgnoreCase))throw new Exception(L.Get("ReconcileBackupInvalid"));return Paths.Safe(State,file.backupReference);}
  FileStream AssistantLock(string folder){string path=Paths.Safe(folder,"operation.lock");if(!File.Exists(path))throw new Exception(L.Get("ReconcileLockMissing"));return new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.None);}
  public ReconciliationPlan ReviewReconciliation(Package package,string assistantState){Paths.CheckLinks(assistantState);using(var gate=AssistantLock(assistantState))return ReviewReconciliationCore(package,assistantState);}
  ReconciliationPlan ReviewReconciliationCore(Package selected,string assistantState){CheckGame();if(NeedsRecovery||File.Exists(Paths.Safe(assistantState,"transaction.json")))throw new Exception(L.Get("ReconcilePending"));var package=Packages.Reload(selected);if(package.Manifest.kind!="localization"||package.Manifest.packageIdentity==null||package.Manifest.scopeId!=ScopeId)throw new Exception(L.Get("ReconcileUnsupported"));if(Packages.InstallSignature(selected)!=Packages.InstallSignature(package))throw new Exception(L.Get("SourceChanged"));WorkshopTargets.VerifySources(package,Root);
   var legacy=ReadAssistant(assistantState,package);var current=ReadRegistry();var old=current.packages.SingleOrDefault(p=>p.id==package.Manifest.id);if(old!=null&&old.kind!="localization")throw new Exception(L.Get("ReconcileUnsupported"));var others=new HashSet<string>(current.packages.Where(p=>p.id!=package.Manifest.id).SelectMany(p=>p.files.Select(f=>f.target)),StringComparer.OrdinalIgnoreCase);var incoming=new HashSet<string>(package.Manifest.files.Select(f=>f.target),StringComparer.OrdinalIgnoreCase);if(incoming.Any(others.Contains))throw new Exception(L.Get("BatchOverlap"));
   var legacyByPath=legacy.files.ToDictionary(f=>f.relative,StringComparer.OrdinalIgnoreCase);var oldByPath=old==null?new Dictionary<string,OwnedFile>(StringComparer.OrdinalIgnoreCase):old.files.ToDictionary(f=>f.target,StringComparer.OrdinalIgnoreCase);bool aligned=old!=null&&old.version==package.Manifest.version&&old.files.Count==legacy.files.Count;int originals=0,differences=0;
   foreach(var f in package.Manifest.files){var proof=legacyByPath[f.target];string source=Paths.Safe(package.Folder,f.source),target=Target(f.target);if(!File.Exists(source)||!Data.Same(Data.Hash(source),f.sha256)||!File.Exists(target)||!Data.Same(Data.Hash(target),f.sha256))throw new Exception(L.Get("ReconcileContentMismatch")+f.target);if(!Data.Same(proof.hash,f.sha256))throw new Exception(L.Get("ReconcileRecordMismatch")+f.target);
    if(proof.hadOriginal){string backup=Paths.Safe(assistantState,"original/"+f.target);if(!Data.ValidHash(proof.originalHash)||!File.Exists(backup)||!Data.Same(Data.Hash(backup),proof.originalHash))throw new Exception(L.Get("ReconcileBackupInvalid")+f.target);originals++;}
    OwnedFile former;if(!oldByPath.TryGetValue(f.target,out former)||!Data.Same(former.hash,f.sha256)||former.hadOriginal!=proof.hadOriginal||proof.hadOriginal&&(!Data.Same(former.originalHash,proof.originalHash)||!File.Exists(Original(former))||!Data.Same(Data.Hash(Original(former)),former.originalHash)))aligned=false;
    if(former!=null&&(former.hadOriginal!=proof.hadOriginal||!Data.Same(former.originalHash,proof.originalHash)))differences++;
   }
   var extra=oldByPath.Values.Where(f=>!incoming.Contains(f.target)).ToList();int changed=0;foreach(var f in extra){string path=Target(f.target);if(!File.Exists(path)||!Data.Same(Data.Hash(path),f.hash)||f.hadOriginal&&(!File.Exists(Original(f))||!Data.Same(Data.Hash(Original(f)),f.originalHash)))changed++;}
   return new ReconciliationPlan{Package=package,AssistantState=Path.GetFullPath(assistantState),ManagerRecordHash=File.Exists(RegistryPath)?Data.Hash(RegistryPath):null,AssistantRecordHash=Data.Hash(Paths.Safe(assistantState,"installed.json")),PackageSignature=Packages.InstallSignature(package),Files=package.Manifest.files.Count,Originals=originals,Retained=extra.Count,RetainedDifferences=changed,BackupDifferences=differences,AlreadyCurrent=aligned};
  }
  AssistantRecord ReadAssistant(string folder,Package package){var record=Data.Read<AssistantRecord>(Paths.Safe(folder,"installed.json"));if(record==null||record.product!="Unturned.AI.Tchinese"||!Data.Same(Path.GetFullPath(record.gameRoot??"" ).TrimEnd('\\'),Root)||record.version!=package.Manifest.version||record.files==null||record.files.Count!=package.Manifest.files.Count)throw new Exception(L.Get("ReconcileRecordMismatch"));var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var f in record.files){if(f==null||!Data.ValidHash(f.hash)||!names.Add(f.relative))throw new Exception(L.Get("ReconcileRecordMismatch"));Paths.CheckTarget(f.relative,"localization",ScopeId);Paths.Safe(Root,f.relative);}if(!names.SetEquals(package.Manifest.files.Select(f=>f.target)))throw new Exception(L.Get("ReconcileRecordMismatch"));return record;}
  public string Reconcile(ReconciliationPlan reviewed){if(reviewed==null)throw new ArgumentNullException("reviewed");Directory.CreateDirectory(State);using(var managerGate=new FileStream(Path.Combine(State,"operation.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None))using(var assistantGate=AssistantLock(reviewed.AssistantState)){
   var fresh=ReviewReconciliationCore(reviewed.Package,reviewed.AssistantState);if(fresh.ManagerRecordHash!=reviewed.ManagerRecordHash||fresh.AssistantRecordHash!=reviewed.AssistantRecordHash||fresh.PackageSignature!=reviewed.PackageSignature)throw new Exception(L.Get("ReconcileChanged"));if(fresh.AlreadyCurrent)return null;
   var record=ReadAssistant(fresh.AssistantState,fresh.Package);var registry=ReadRegistry();var old=registry.packages.SingleOrDefault(p=>p.id==fresh.Package.Manifest.id);string token=Guid.NewGuid().ToString("N"),history=Paths.Safe(State,"ReconcileHistory/"+token);Directory.CreateDirectory(history);if(File.Exists(RegistryPath)){File.Copy(RegistryPath,Paths.Safe(history,"manager-before.json"));if(Data.Hash(Paths.Safe(history,"manager-before.json"))!=fresh.ManagerRecordHash)throw new Exception(L.Get("ReconcileChanged"));}File.Copy(Paths.Safe(fresh.AssistantState,"installed.json"),Paths.Safe(history,"assistant-record.json"));if(Data.Hash(Paths.Safe(history,"assistant-record.json"))!=fresh.AssistantRecordHash)throw new Exception(L.Get("ReconcileChanged"));
   var adopted=new InstalledPackage{id=fresh.Package.Manifest.id,name=fresh.Package.Manifest.name,version=fresh.Package.Manifest.version,kind="localization",scopeId=ScopeId,files=new List<OwnedFile>()};foreach(var file in record.files){string backupRef=null;if(file.hadOriginal){backupRef="ImportedOriginals/"+token+"/"+Data.Key(file.relative)+".bak";string dest=Paths.Safe(State,backupRef);Directory.CreateDirectory(Path.GetDirectoryName(dest));File.Copy(Paths.Safe(fresh.AssistantState,"original/"+file.relative),dest,false);if(!Data.Same(Data.Hash(dest),file.originalHash))throw new Exception(L.Get("ReconcileBackupInvalid")+file.relative);}adopted.files.Add(new OwnedFile{target=file.relative,hash=file.hash,hadOriginal=file.hadOriginal,originalHash=file.originalHash,backupReference=backupRef});}
   foreach(var f in adopted.files){string target=Target(f.target);if(!File.Exists(target)||!Data.Same(Data.Hash(target),f.hash))throw new Exception(L.Get("ReconcileContentMismatch")+f.target);}if((File.Exists(RegistryPath)?Data.Hash(RegistryPath):null)!=fresh.ManagerRecordHash||Data.Hash(Paths.Safe(fresh.AssistantState,"installed.json"))!=fresh.AssistantRecordHash||File.Exists(Paths.Safe(fresh.AssistantState,"transaction.json")))throw new Exception(L.Get("ReconcileChanged"));
   var adoptedNames=new HashSet<string>(adopted.files.Select(f=>f.target),StringComparer.OrdinalIgnoreCase);var retained=old==null?new List<OwnedFile>():old.files.Where(f=>!adoptedNames.Contains(f.target)).ToList();registry.packages.RemoveAll(p=>p.id==adopted.id);registry.packages.Add(adopted);if(retained.Count>0)registry.packages.Add(new InstalledPackage{id=adopted.id+".retained."+token.Substring(0,8),name=L.Get("RetainedFiles"),version=old.version,kind=old.kind,scopeId=old.scopeId,retained=true,files=retained});Data.Write(Paths.Safe(history,"review.json"),new{version=adopted.version,root=Root,files=fresh.Files,backups=fresh.Originals,retained=fresh.Retained,unresolved=fresh.RetainedDifferences,assistant=fresh.AssistantState});Data.Write(RegistryPath,registry);return history;
  }}
 }
}
